command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/docs-current-state-20261005"
$expectedWork="2b271f5fa83684b7f9b91f1ae15ccde194f0cde9"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "cleanup fetch failed"}
$workRef="refs/remotes/origin/"+$branch
$workSha=(& git rev-parse $workRef).Trim()
if($LASTEXITCODE -ne 0 -or $workSha -ne $expectedWork){throw "work branch moved: $workSha"}
$mainTree=(& git rev-parse "refs/remotes/origin/main^{tree}").Trim()
if($LASTEXITCODE -ne 0){throw "failed to resolve main tree"}
$workTree=(& git rev-parse ($workRef+"^{tree}")).Trim()
if($LASTEXITCODE -ne 0){throw "failed to resolve work tree"}
if($mainTree -ne $workTree){throw "refuse cleanup: merged main tree differs from work branch tree"}
& git push origin --delete $branch
if($LASTEXITCODE -ne 0){throw "failed to delete merged docs work branch"}
& git fetch origin --prune --no-tags
if($LASTEXITCODE -ne 0){throw "post-delete fetch failed"}
if(& git show-ref --verify --quiet $workRef){throw "docs work branch still exists"}
Write-Host "DOCS_WORK_BRANCH_CLEANUP=PASS"
